sys_script_include.script:
var FHIRPatientContextAjax = Class.create();
FHIRPatientContextAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getPatientContext: function() {
        var service = new x_1886160_fhir_p_0.FHIRPatientContextService();
        var result = service.run(
            this.getParameter('sysparm_connection'),
            this.getParameter('sysparm_mrn'),
            this.getParameter('sysparm_system')
        );
        return JSON.stringify(result);
    },

    type: 'FHIRPatientContextAjax'
});
